#!/usr/bin/env python3
from __future__ import annotations
import base64,re,shutil,subprocess,sys,time
from pathlib import Path

PATCH_ID='MEMEFLOW_DISCOVERY_ROUTER_V1'
STAMP=time.strftime('%Y%m%d-%H%M%S')
PAYLOADS={'discovery-source.mjs': '', 'dex-discovery-feed.mjs': '', 'system-source.html': ''}

def log(x): print('[DISCOVERY-V1] '+str(x),flush=True)

def find_root():
    candidates=[Path.cwd(),Path.cwd()/'memeflow-app',Path.home()/'workspace',Path.home()/'workspace'/'memeflow-app',Path('/home/runner/workspace'),Path('/home/runner/workspace/memeflow-app'),Path('/workspace'),Path('/workspace/memeflow-app')]
    for r in candidates:
        try:r=r.resolve()
        except:continue
        if (r/'app-server.mjs').is_file() and (r/'src/settings.mjs').is_file(): return r
    for base in [Path('/home/runner/workspace'),Path.cwd()]:
        if not base.exists(): continue
        for p in base.glob('**/app-server.mjs'):
            if (p.parent/'src/settings.mjs').is_file(): return p.parent.resolve()
    raise RuntimeError('MEMEFLOW project root not found')

ROOT=find_root(); SRC=ROOT/'src'; APP=ROOT/'app-server.mjs'; SETTINGS=SRC/'settings.mjs'; EVALUATE=SRC/'evaluate.mjs'
BACK=ROOT/f'.discovery-router-v1-backup-{STAMP}'; BACK.mkdir(parents=True,exist_ok=True)
changed=[]

def rel(p): return p.resolve().relative_to(ROOT.resolve())
def backup(p):
    if p in changed:return
    if p.exists():
        d=BACK/rel(p);d.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,d)
    changed.append(p)
def write(p,text):
    backup(p);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8');log('patched '+str(rel(p)))
def write_payload(name,target): write(target,base64.b64decode(PAYLOADS[name]).decode('utf-8'))
def rollback(err):
    log('ERROR: '+str(err))
    for p in reversed(changed):
        b=BACK/rel(p)
        try:
            if b.exists(): shutil.copy2(b,p);log('restored '+str(rel(p)))
            elif p.exists(): p.unlink();log('removed new '+str(rel(p)))
        except Exception as e: log('rollback warning '+str(e))
    log('ROLLBACK COMPLETE');sys.exit(1)

def replace_once(text,old,new,label):
    n=text.count(old)
    if n!=1: raise RuntimeError(f'{label}: expected exactly 1 anchor, found {n}')
    return text.replace(old,new,1)

def patch_settings(text):
    text=replace_once(text,"const PLATFORMS=['pump'];","const PLATFORMS=['pump','dex'];",'settings platform list')
    text=replace_once(text,"launchPlatforms:['pump'],","launchPlatforms:['pump','dex'],",'settings defaults')
    old=""" // Current discovery backend is Pump.fun only. Do not expose a pretend multi-launchpad filter.\n o.launchPlatforms=['pump'];"""
    new=""" // Discovery source is server-global (PUMP / DEX / HYBRID).\n // Keep both normalized here so the selected engine source is not discarded downstream.\n o.launchPlatforms=['pump','dex'];"""
    text=replace_once(text,old,new,'settings normalize source')
    oldv="if(!Array.isArray(s.launchPlatforms)||s.launchPlatforms.length!==1||s.launchPlatforms[0]!=='pump')errors.push('Current discovery supports Pump.fun only.');"
    newv="if(!Array.isArray(s.launchPlatforms)||s.launchPlatforms.some(x=>!PLATFORMS.includes(String(x).toLowerCase())))errors.push('Invalid launch platform. Supported discovery platforms are pump and dex.');"
    text=replace_once(text,oldv,newv,'settings validation')
    return text

def patch_evaluate(text):
    old="""  if (\n    finite(s.maxDeveloperPct) &&\n    Number(s.maxDeveloperPct) > 0\n  ) {\n    addGate(\n      'Developer concentration',\n      token.developerPct == null\n        ? null\n        : Number(token.developerPct) <= Number(s.maxDeveloperPct),\n      `developer above ${s.maxDeveloperPct}%`\n    );\n  }"""
    new="""  const dexCreatorUnavailable =\n    String(token.launchPlatform || '').toLowerCase() === 'dex' &&\n    token.creator == null &&\n    token.developerPct == null;\n\n  if (\n    finite(s.maxDeveloperPct) &&\n    Number(s.maxDeveloperPct) > 0\n  ) {\n    if (dexCreatorUnavailable) {\n      gates.push({\n        name: 'Developer concentration',\n        status: 'N/A',\n        pass: true,\n        reason: 'creator identity unavailable from confirmed DEX pool'\n      });\n    } else {\n      addGate(\n        'Developer concentration',\n        token.developerPct == null\n          ? null\n          : Number(token.developerPct) <= Number(s.maxDeveloperPct),\n        `developer above ${s.maxDeveloperPct}%`\n      );\n    }\n  }"""
    return replace_once(text,old,new,'DEX developer N/A gate')

def patch_app(text):
    imp="import { startPumpLiveTradeFeed } from './src/pump-live-trade-feed.mjs'; // MEMEFLOW_V12_21_LIVE_TRADE_STREAM_HOLDER_FEED"
    newimp=imp+"\nimport { DiscoverySourceController } from './src/discovery-source.mjs'; // "+PATCH_ID+"\nimport { startDexDiscoveryFeed } from './src/dex-discovery-feed.mjs'; // "+PATCH_ID
    text=replace_once(text,imp,newimp,'app imports')

    rootline="const root=path.dirname(fileURLToPath(import.meta.url)),dataDir=path.resolve(root,process.env.DATA_DIR||'data'),store=new JsonStore(dataDir);"
    rootnew=rootline+"\nconst __discoverySource=new DiscoverySourceController({dataDir,defaultMode:process.env.DISCOVERY_SOURCE_MODE||'dex'});\nconst __discoverySourceAllows=source=>__discoverySource.allows(source);"
    text=replace_once(text,rootline,rootnew,'source controller init')

    start="function startDiscovery(i=0){\n  if(process.env.DISCOVERY_ENABLED==='false'||!wsUrls.length){discovery.error='SOLANA_WS_URLS not configured';return}"
    startnew="function startDiscovery(i=0){\n  if(!__discoverySourceAllows('pump')){discovery.connected=false;discovery.error=null;return}\n  if(process.env.DISCOVERY_ENABLED==='false'||!wsUrls.length){discovery.error='SOLANA_WS_URLS not configured';return}"
    text=replace_once(text,start,startnew,'Pump discovery source gate')

    cap="capabilities:{liveAutomation:hasLiveEntitlement(u),paperAutomation:true,discoveryPlatforms:['pump'],adaptiveProfile:false}"
    capnew="capabilities:{liveAutomation:hasLiveEntitlement(u),paperAutomation:true,discoveryPlatforms:['pump','dex'],discoverySourceMode:__discoverySource.mode,adaptiveProfile:false}"
    text=replace_once(text,cap,capnew,'settings capabilities')

    route_anchor=" if(url.pathname==='/api/settings'&&req.method==='GET'){"
    routes=""" if(url.pathname==='/api/discovery-source'&&req.method==='GET')return json(res,200,__discoverySourceStatus());\n if(url.pathname==='/api/discovery-source'&&req.method==='POST'){\n   if(!u.isOwner)return json(res,403,{error:'OWNER_REQUIRED',message:'Only the owner can switch the global discovery source.'});\n   const b=await body(req);\n   try{__discoverySource.set(b?.mode);__applyDiscoverySourceMode();return json(res,200,__discoverySourceStatus())}\n   catch(e){return json(res,400,{error:e.code||'INVALID_DISCOVERY_SOURCE',message:e.message})}\n }\n"""+route_anchor
    text=replace_once(text,route_anchor,routes,'discovery source API routes')

    listen="  startDiscovery();"
    text=replace_once(text,listen,"  __applyDiscoverySourceMode();",'server source startup')

    pattern=re.compile(r"// MEMEFLOW_V12_21_LIVE_TRADE_STREAM_HOLDER_FEED\nconst __pumpLiveTradeFeed=startPumpLiveTradeFeed\(\{(?P<body>.*?)\n\}\);",re.S)
    m=pattern.search(text)
    if not m: raise RuntimeError('Pump live feed block anchor not found')
    body=m.group('body')
    manager=f"""// MEMEFLOW_V12_21_LIVE_TRADE_STREAM_HOLDER_FEED\n// {PATCH_ID}: feeds are now owned by the source router.\nconst __pumpLiveTradeFeedOpts={{\n{body}\n}};\nlet __pumpLiveTradeFeed=null;\nlet __dexDiscoveryFeed=null;\n\nasync function __applyDexDiscovery(info){{\n  const mint=info?.mint;if(!mint)return;\n  const existing=store.state?.tokens?.[mint]||null;\n  const identity={{...(info.identity||{{}})}};\n  if(existing){{\n    store.setToken(mint,{{...identity,creator:existing.creator||identity.creator||null,creatorStatus:existing.creator?'known':identity.creatorStatus,discoveredAt:existing.discoveredAt||identity.discoveredAt,launchPlatform:existing.launchPlatform||identity.launchPlatform,protocol:existing.protocol||identity.protocol,source:existing.source||identity.source,dexListedAt:Date.now()}});\n  }}else{{\n    store.addToken({{...identity,dexListedAt:Date.now()}});\n  }}\n  try{{await enrich(mint,null)}}catch(e){{console.error('[DEX DISCOVERY] enrich',mint,e?.message||e)}}\n  const current=store.state?.tokens?.[mint]||{{}};\n  const dq=current.holderFresh===true?0.95:0.80;\n  const updated=store.setToken(mint,{{...(info.market||{{}}),dataQuality:Math.max(Number(current.dataQuality)||0,dq),dexConfirmed:true}});\n  try{{await evaluateAll(updated)}}catch(e){{console.error('[DEX DISCOVERY] evaluate',mint,e?.message||e)}}\n  try{{publish(mint)}}catch{{}}\n}}\nasync function __applyDexMarket(mint,patch){{\n  const current=store.state?.tokens?.[mint];if(!current)return;\n  const dq=current.holderFresh===true?0.95:0.80;\n  const updated=store.setToken(mint,{{...(patch||{{}}),dataQuality:Math.max(Number(current.dataQuality)||0,dq),dexConfirmed:true}});\n  try{{await evaluateAll(updated)}}catch{{}}\n  try{{publish(mint)}}catch{{}}\n}}\nfunction __startPumpLiveFeed(){{if(!__pumpLiveTradeFeed)__pumpLiveTradeFeed=startPumpLiveTradeFeed(__pumpLiveTradeFeedOpts)}}\nfunction __stopPumpLiveFeed(){{if(__pumpLiveTradeFeed){{try{{__pumpLiveTradeFeed.stop?.()}}catch{{}}__pumpLiveTradeFeed=null}}}}\nfunction __startDexFeed(){{if(!__dexDiscoveryFeed)__dexDiscoveryFeed=startDexDiscoveryFeed({{rpc,wsUrls,onDiscover:__applyDexDiscovery,onMarket:__applyDexMarket}})}}\nfunction __stopDexFeed(){{if(__dexDiscoveryFeed){{try{{__dexDiscoveryFeed.stop?.()}}catch{{}}__dexDiscoveryFeed=null}}}}\nfunction __stopPumpCreateDiscovery(){{\n  clearTimeout(wsTimer);wsTimer=null;\n  try{{if(ws)ws.onclose=null}}catch{{}}\n  try{{ws?.close?.()}}catch{{}}\n  ws=null;discovery.connected=false;discovery.error=null;\n}}\nfunction __applyDiscoverySourceMode(){{\n  if(__discoverySourceAllows('pump')){{__startPumpLiveFeed();if(!ws)startDiscovery()}}else{{__stopPumpLiveFeed();__stopPumpCreateDiscovery()}}\n  if(__discoverySourceAllows('dex'))__startDexFeed();else __stopDexFeed();\n  console.log('[DISCOVERY SOURCE]',__discoverySource.mode);\n  return __discoverySource.mode;\n}}\nfunction __discoverySourceStatus(){{\n  const pumpTrade=__pumpLiveTradeFeed?.metrics?.()||null,dex=__dexDiscoveryFeed?.metrics?.()||null;\n  return {{source:__discoverySource.snapshot(),pump:{{connected:Boolean(discovery.connected||pumpTrade?.connected),createConnected:Boolean(discovery.connected),trade:pumpTrade}},dex}};\n}}"""
    text=text[:m.start()]+manager+text[m.end():]

    # Extend existing diagnostics where present without changing their meaning.
    text=text.replace("liveTradeFeed:__pumpLiveTradeFeed?.metrics?.()||null,","liveTradeFeed:__pumpLiveTradeFeed?.metrics?.()||null,dexDiscovery:__dexDiscoveryFeed?.metrics?.()||null,discoverySource:__discoverySource.snapshot(),")
    return text

try:
    log('root: '+str(ROOT))
    app=APP.read_text(encoding='utf-8');settings=SETTINGS.read_text(encoding='utf-8');evaluate=EVALUATE.read_text(encoding='utf-8')
    if PATCH_ID in app:
        log('patch already installed');sys.exit(0)

    # Preflight all transformations in memory before touching project files.
    new_settings=patch_settings(settings)
    new_evaluate=patch_evaluate(evaluate)
    new_app=patch_app(app)

    write_payload('discovery-source.mjs',SRC/'discovery-source.mjs')
    write_payload('dex-discovery-feed.mjs',SRC/'dex-discovery-feed.mjs')
    write_payload('system-source.html',ROOT/'system-source.html')
    write(SETTINGS,new_settings);write(EVALUATE,new_evaluate);write(APP,new_app)

    for f in [APP,SETTINGS,EVALUATE,SRC/'discovery-source.mjs',SRC/'dex-discovery-feed.mjs']:
        r=subprocess.run(['node','--check',str(f)],cwd=ROOT,capture_output=True,text=True)
        if r.returncode: raise RuntimeError('node --check failed for '+str(rel(f))+':\n'+(r.stderr or r.stdout))
        log('syntax OK '+str(rel(f)))

    # Static invariants: Pump path remains in the code, DEX path is additive and reversible.
    a=APP.read_text(encoding='utf-8');s=SETTINGS.read_text(encoding='utf-8');e=EVALUATE.read_text(encoding='utf-8')
    required=[PATCH_ID,"__discoverySourceAllows('pump')","startDexDiscoveryFeed","/api/discovery-source","__applyDiscoverySourceMode"]
    for token in required:
        if token not in a: raise RuntimeError('validation missing in app-server.mjs: '+token)
    if "const PUMP='6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P'" not in a: raise RuntimeError('Pump original program path was unexpectedly removed')
    if "o.launchPlatforms=['pump','dex'];" not in s: raise RuntimeError('settings did not enable normalized pump+dex routing')
    if "creator identity unavailable from confirmed DEX pool" not in e: raise RuntimeError('DEX creator N/A rule missing')

    log('INSTALL COMPLETE')
    log('default source on first restart: DEX')
    log('PUMP path preserved and can be restored instantly')
    log('DEX programs: PumpSwap + Raydium CPMM + Raydium CLMM')
    log('DEX pair must be SOL-paired and have real DEX Screener transaction activity before admission')
    log('source control page: /system-source.html')
    log('backup: '+str(BACK))
    log('Restart the Replit workflow/app, then open /system-source.html')
except Exception as e:
    rollback(e)
